import { act, fireEvent, render, screen, within } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import App from "./App";
import { AgentStreamProvider } from "./data/AgentStream";

function renderDashboard(seed = 7) {
  return render(
    <AgentStreamProvider seed={seed} tickMs={1000}>
      <App />
    </AgentStreamProvider>,
  );
}

function tickLabel(): string {
  return screen.getByText(/TICK \d{4}/).textContent ?? "";
}

describe("trading desk dashboard", () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  it("renders exactly eight distinct agent cards, the pixel room and both financial charts", () => {
    renderDashboard();

    const cards = screen.getAllByTestId("agent-card");
    expect(cards).toHaveLength(8);

    const names = cards.map((card) => within(card).getByRole("heading", { level: 3 }).textContent);
    expect(names).toEqual(["CHIEF", "SCAN", "VET", "SOCIAL", "SIZE", "FILLS", "RISK", "CRAWLER"]);
    expect(new Set(cards.map((card) => card.getAttribute("data-agent"))).size).toBe(8);

    expect(screen.getByTestId("pixel-room")).toBeInTheDocument();
    expect(screen.getByTestId("pixel-room").querySelector(".room-svg")).toBeInTheDocument();
    expect(screen.getByTestId("equity-chart")).toBeInTheDocument();
    expect(screen.getByTestId("candle-chart")).toBeInTheDocument();
    expect(screen.getByTestId("threshold-panel")).toBeInTheDocument();
    expect(screen.getByText("thresholds.py")).toBeInTheDocument();
    expect(screen.getByText(/SIM LIVE/)).toBeInTheDocument();
    expect(tickLabel()).toContain("TICK 0000");
  });

  it("drives cards, charts and the room from one interval tick", () => {
    renderDashboard();

    const firstCard = screen.getAllByTestId("agent-card")[0];
    const valueBefore = firstCard.querySelector(".agent-value")?.textContent;
    const equityPathBefore = screen
      .getByTestId("equity-chart")
      .querySelector(".equity-line--core")
      ?.getAttribute("d");

    act(() => {
      vi.advanceTimersByTime(1000);
    });

    expect(tickLabel()).toContain("TICK 0001");
    expect(firstCard.querySelector(".agent-value")?.textContent).not.toBe(valueBefore);
    const equityPathAfter = screen
      .getByTestId("equity-chart")
      .querySelector(".equity-line--core")
      ?.getAttribute("d");
    expect(equityPathAfter).not.toBe(equityPathBefore);
    expect(screen.getByTestId("candle-chart").querySelectorAll(".candle-body").length).toBeGreaterThan(10);
    expect(screen.getByTestId("pixel-room").querySelectorAll(".station").length).toBe(6);
  });

  it("pauses, steps one tick while held, then resumes the single stream", () => {
    renderDashboard();

    fireEvent.click(screen.getByRole("button", { name: "Pause simulation" }));
    expect(screen.getByRole("status")).toHaveTextContent("SIMULATION HELD // RESUME TO STREAM");
    expect(tickLabel()).toContain("TICK 0000");

    act(() => {
      vi.advanceTimersByTime(3000);
    });
    expect(tickLabel()).toContain("TICK 0000");

    fireEvent.click(screen.getByRole("button", { name: "Advance simulation one tick" }));
    expect(tickLabel()).toContain("TICK 0001");
    expect(screen.getByRole("status")).toBeInTheDocument();

    fireEvent.click(screen.getByRole("button", { name: "Resume simulation" }));
    expect(screen.queryByRole("status")).not.toBeInTheDocument();
    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(tickLabel()).toContain("TICK 0002");
  });

  it("shows an equity tooltip on pointer movement and clears it on leave", () => {
    renderDashboard();
    const chart = screen.getByTestId("equity-chart");
    vi.spyOn(chart, "getBoundingClientRect").mockReturnValue({
      x: 0,
      y: 0,
      left: 0,
      top: 0,
      right: 600,
      bottom: 260,
      width: 600,
      height: 260,
      toJSON: () => ({}),
    } as DOMRect);

    expect(screen.queryByTestId("chart-tooltip")).not.toBeInTheDocument();
    fireEvent.pointerMove(chart, { clientX: 330, clientY: 120 });

    const tooltip = screen.getByTestId("chart-tooltip");
    expect(tooltip).toHaveTextContent("TICK");
    expect(tooltip.textContent).toMatch(/\$[\d,]+\.\d{2}/);

    fireEvent.pointerLeave(chart);
    expect(screen.queryByTestId("chart-tooltip")).not.toBeInTheDocument();
  });

  it("renders order book and threshold values from the same snapshot", () => {
    renderDashboard();
    const analysis = screen.getByTestId("analysis-panel");
    expect(within(analysis).getByText("BOOK")).toBeInTheDocument();
    expect(within(analysis).getByText("ASK")).toBeInTheDocument();
    expect(within(analysis).getByText("BID")).toBeInTheDocument();
    expect(within(analysis).getAllByText(/DOPE \/ SOL/).length).toBeGreaterThan(0);

    const rows = screen.getByTestId("threshold-panel").querySelectorAll(".threshold-list li");
    expect(rows).toHaveLength(8);
    expect(screen.getByText("MIN_AGE_SEC")).toBeInTheDocument();
    expect(screen.getByText("SOCIAL_MIN")).toBeInTheDocument();
    expect(screen.getByText("MAX_SLIPPAGE")).toBeInTheDocument();
  });
});
